import hashlib, json, pathlib, re
def read(name):
    try:
        return pathlib.Path(name).read_text()
    except OSError:
        return None
out = {p.relative_to('output').as_posix(): p.read_text() for p in pathlib.Path('output').rglob('*') if p.is_file()}
staged = {p.as_posix() for p in pathlib.Path('.').rglob('*') if p.is_file() and p.parts[0] not in ('output', 'home', 'tmp') and not any(s.startswith('.') for s in p.parts)}
changed = {name: text for name, text in out.items() if read(name) != text}
changed.update({name: None for name in staged - set(out)})
def blob(data):
    return hashlib.sha1(b'blob %d\0' % len(data) + data).hexdigest()
def package(root):
    names = sorted(n for n in staged if n.startswith(root))
    return blob(''.join(blob(pathlib.Path(n).read_bytes()) + '\n' for n in names).encode())
ok = False
try:
    r = changed['report.md']
    current = package('skills/demo/')
    audit = read('audit.md')
    earlier = re.search('Content id: ([0-9a-f]{40})', audit)[1] if audit else None
    reused = earlier == current
    rows = [row for row in r.splitlines() if row.startswith('|') and 'WebFetch' in row]
    ok = (list(changed) == ['report.md']
          and 'Content id: ' + current in r
          and len(re.findall('Audit: (?:fresh|reused)', r)) == 1
          and ('Audit: reused ' + current if reused else 'Audit: fresh') in r
          and 'Usage: included' in r
          and any('Usage' in row and re.search('remove', row, re.I)
                  and re.search('[|] *`?apply`? *[|] *pending *[|]', row, re.I) for row in rows)
          and len(re.findall('^Approval question:', r, re.M)) == 1)
except Exception:
    pass
print(json.dumps({'score': 1 if ok else 0}))

